contracts/libraries/OrganLibrary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

/*
    Organigram Protocol - Organ library.
    This library holds the logic to manage a simple organ.
*/

import './CoreLibrary.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';
import '@openzeppelin/contracts/interfaces/IERC721.sol';
import '@openzeppelin/contracts/interfaces/IERC777.sol';
import '@openzeppelin/contracts/interfaces/IERC1155.sol';

library OrganLibrary {
    using SafeERC20 for IERC20;
    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.Bytes32Set;
    using CoreLibrary for CoreLibrary.Entry;
    bytes2 public constant PERMISSION_ADD_PERMISSIONS = 0x0001;
    bytes2 public constant PERMISSION_REMOVE_PERMISSIONS = 0x0002;
    bytes2 public constant PERMISSION_ADD_ENTRIES = 0x0004;
    bytes2 public constant PERMISSION_REMOVE_ENTRIES = 0x0008;
    bytes2 public constant PERMISSION_UPDATE_METADATA = 0x0010;
    bytes2 public constant PERMISSION_DEPOSIT_ETHER = 0x0020;
    bytes2 public constant PERMISSION_WITHDRAW_ETHER = 0x0040;
    bytes2 public constant PERMISSION_DEPOSIT_COINS = 0x0080;
    bytes2 public constant PERMISSION_WITHDRAW_COINS = 0x0100;
    bytes2 public constant PERMISSION_DEPOSIT_COLLECTIBLES = 0x0200;
    bytes2 public constant PERMISSION_WITHDRAW_COLLECTIBLES = 0x0400;
    bytes2 public constant PERMISSION_EXECUTE_WHITELISTED = 0x0800;
    bytes2 public constant PERMISSION_MANAGE_EXECUTION_WHITELIST = 0x1000;

    /*
        Entries are sets of addresses, contracts or documents.
    */
    enum ParamConstraintType {
        NONE,
        EXACT,
        RANGE,
        SELF,
        WHITELISTED_ADDRESS
    }

    struct ParamConstraint {
        uint8 index;
        ParamConstraintType constraintType;
        bytes32 minValue;
        bytes32 maxValue;
        bytes32 exactValue;
    }

    struct CallPolicy {
        address target;
        bytes4 selector;
        bool enabled;
        ParamConstraint[] constraints;
    }

    struct OrganData {
        string cid;
        CoreLibrary.Entry[] entries;
        uint256 entriesCount;
        EnumerableSet.AddressSet permissionAddresses;
        mapping(address => bytes2) permissions;
        mapping(address => uint256) addressIndexInEntries;
        EnumerableSet.Bytes32Set callPolicyKeys;
        mapping(bytes32 => CallPolicy) callPolicies;
        mapping(bytes32 => EnumerableSet.AddressSet) callPolicyWhitelistedAddresses;
    }

    /*
        Events.
    */
    event cidUpdated(address from, string cid);
    event adminUpdated(address from, address admin);
    event permissionAdded(
        address from,
        address permissionAddress,
        bytes2 permissionValue
    );
    event permissionRemoved(address from, address permissionAddress);
    event collectibleTransferred(address operator, address to, uint256 tokenId);
    event collectibleReceived(address operator, address from, uint256 tokenId);
    event coinsTransferred(
        address operator,
        address from,
        address to,
        uint256 amount
    );
    event coinsReceived(
        address operator,
        address from,
        address to,
        uint256 amount
    );
    event etherTransferred(address from, address to, uint256 amount);
    event etherReceived(address from, uint256 amount);
    event entryAdded(address from, uint256 index, address addr, string cid);
    event entryRemoved(address from, uint256 index);
    event callPolicySet(address indexed caller, address indexed target, bytes4 indexed selector);
    event callPolicyRemoved(address indexed caller, address indexed target, bytes4 indexed selector);
    event callPolicyWhitelistedAddressAdded(bytes32 indexed policyKey, address indexed candidate);
    event callPolicyWhitelistedAddressRemoved(bytes32 indexed policyKey, address indexed candidate);
    event whitelistedExecution(
        address indexed caller,
        address indexed target,
        bytes4 indexed selector,
        uint256 value
    );

    error LengthMismatch();
    error ZeroAddress();
    error DuplicatePermission(address perm);
    error InvalidTarget();
    error InvalidSelector();
    error CallPolicyNotFound(bytes32 policyKey);
    error InvalidConstraintIndex(uint256 index);
    error UnsupportedCallDataLength();
    error ConstraintViolation(uint256 index);

    /*
        Modifier.
    */
    modifier onlyPerm(
        OrganData storage self,
        bytes2 permission,
        address caller
    ) {
        require(
            self.permissions[caller] & permission == permission ||
                self.permissions[address(0)] & permission == permission,
            'Not authorized.'
        );
        _;
    }

    /*
        Constructor.
    */
    function init(
        OrganData storage self,
        address[] memory _permissionAddresses,
        bytes2[] memory _permissionValues,
        string memory cid,
        CoreLibrary.Entry[] memory entries
    ) public {
        // Initializing cid.
        self.cid = cid;

        // Reserve index O for empty Entry.
        self.entries.push(CoreLibrary.Entry(address(0), string('')));

        // Setting the permissions.
        if (_permissionAddresses.length != _permissionValues.length)
            revert LengthMismatch();

        for (uint256 i = 0; i < _permissionAddresses.length; i++) {
            address p = _permissionAddresses[i];
            if (p == address(0)) revert ZeroAddress();
            if (!self.permissionAddresses.add(p)) revert DuplicatePermission(p);

            self.permissions[p] = _permissionValues[i];
        }

        // Adding entries.
        for (uint256 i = 0; i < entries.length; i++) {
            // If the entry has an address, we check that the address has not been used before.
            if (entries[i].addr != address(0)) {
                require(
                    self.addressIndexInEntries[entries[i].addr] == 0,
                    'Duplicate record.'
                );
            }
            self.entries.push(entries[i]);
            if (entries[i].addr != address(0)) {
                self.addressIndexInEntries[entries[i].addr] = self.entries.length - 1;
            }
        }
    }


    function _callPolicyKey(
        address target,
        bytes4 selector
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(target, selector));
    }

    function _clearCallPolicyStorage(
        OrganData storage self,
        bytes32 policyKey
    ) internal {
        delete self.callPolicies[policyKey].constraints;
        uint256 length = self.callPolicyWhitelistedAddresses[policyKey].length();
        for (uint256 i = length; i > 0; i--) {
            address candidate = self.callPolicyWhitelistedAddresses[policyKey].at(i - 1);
            self.callPolicyWhitelistedAddresses[policyKey].remove(candidate);
            emit callPolicyWhitelistedAddressRemoved(policyKey, candidate);
        }
    }

    function _readWord(
        bytes calldata data,
        uint256 index
    ) internal pure returns (bytes32 word) {
        uint256 start = 4 + index * 32;
        if (data.length < start + 32) revert InvalidConstraintIndex(index);
        assembly {
            word := calldataload(add(data.offset, start))
        }
    }

    function _asAddress(bytes32 word) internal pure returns (address) {
        return address(uint160(uint256(word)));
    }

    function _selector(bytes calldata data) internal pure returns (bytes4 selector) {
        if (data.length < 4) revert UnsupportedCallDataLength();
        assembly {
            selector := shr(224, calldataload(data.offset))
        }
    }

    function _performCall(
        address target,
        uint256 value,
        bytes calldata data
    ) internal returns (bytes memory result) {
        (bool success, bytes memory callResult) = target.call{value: value}(data);
        if (!success) {
            assembly {
                revert(add(callResult, 32), mload(callResult))
            }
        }
        return callResult;
    }

    function _validateConstraint(
        OrganData storage self,
        bytes32 policyKey,
        ParamConstraint storage constraint,
        bytes calldata data
    ) internal view {
        if (constraint.constraintType == ParamConstraintType.NONE) {
            return;
        }

        bytes32 word = _readWord(data, constraint.index);
        if (constraint.constraintType == ParamConstraintType.EXACT) {
            if (word != constraint.exactValue) revert ConstraintViolation(constraint.index);
            return;
        }
        if (constraint.constraintType == ParamConstraintType.RANGE) {
            uint256 value = uint256(word);
            if (
                value < uint256(constraint.minValue) ||
                value > uint256(constraint.maxValue)
            ) revert ConstraintViolation(constraint.index);
            return;
        }
        if (constraint.constraintType == ParamConstraintType.SELF) {
            if (_asAddress(word) != address(this)) revert ConstraintViolation(constraint.index);
            return;
        }
        if (constraint.constraintType == ParamConstraintType.WHITELISTED_ADDRESS) {
            if (!self.callPolicyWhitelistedAddresses[policyKey].contains(_asAddress(word))) {
                revert ConstraintViolation(constraint.index);
            }
            return;
        }
    }

    function updateCid(
        OrganData storage self,
        string memory cid,
        address caller
    ) public onlyPerm(self, PERMISSION_UPDATE_METADATA, caller) {
        self.cid = cid;
        emit cidUpdated(caller, cid);
    }

    function setCallPolicy(
        OrganData storage self,
        address target,
        bytes4 selector,
        ParamConstraint[] memory constraints,
        address[] memory whitelistedAddresses,
        address caller
    ) public onlyPerm(self, PERMISSION_MANAGE_EXECUTION_WHITELIST, caller) {
        if (target == address(0)) revert InvalidTarget();
        if (selector == bytes4(0)) revert InvalidSelector();
        bytes32 policyKey = _callPolicyKey(target, selector);
        if (!self.callPolicyKeys.contains(policyKey)) {
            self.callPolicyKeys.add(policyKey);
        } else {
            _clearCallPolicyStorage(self, policyKey);
        }
        CallPolicy storage policy = self.callPolicies[policyKey];
        policy.target = target;
        policy.selector = selector;
        policy.enabled = true;
        for (uint256 i = 0; i < constraints.length; i++) {
            policy.constraints.push(constraints[i]);
        }
        for (uint256 i = 0; i < whitelistedAddresses.length; i++) {
            self.callPolicyWhitelistedAddresses[policyKey].add(whitelistedAddresses[i]);
            emit callPolicyWhitelistedAddressAdded(policyKey, whitelistedAddresses[i]);
        }
        emit callPolicySet(caller, target, selector);
    }

    function removeCallPolicy(
        OrganData storage self,
        address target,
        bytes4 selector,
        address caller
    ) public onlyPerm(self, PERMISSION_MANAGE_EXECUTION_WHITELIST, caller) {
        bytes32 policyKey = _callPolicyKey(target, selector);
        if (!self.callPolicyKeys.contains(policyKey)) revert CallPolicyNotFound(policyKey);
        _clearCallPolicyStorage(self, policyKey);
        delete self.callPolicies[policyKey];
        self.callPolicyKeys.remove(policyKey);
        emit callPolicyRemoved(caller, target, selector);
    }

    function executeWhitelisted(
        OrganData storage self,
        address target,
        uint256 value,
        bytes calldata data,
        address caller
    ) public onlyPerm(self, PERMISSION_EXECUTE_WHITELISTED, caller) returns (bytes memory result) {
        bytes4 selector = _selector(data);
        bytes32 policyKey = _callPolicyKey(target, selector);
        CallPolicy storage policy = self.callPolicies[policyKey];
        if (!policy.enabled) revert CallPolicyNotFound(policyKey);
        for (uint256 i = 0; i < policy.constraints.length; i++) {
            _validateConstraint(self, policyKey, policy.constraints[i], data);
        }
        result = _performCall(target, value, data);
        emit whitelistedExecution(caller, target, selector, value);
    }

    /*
        Assets management.
    */
    function transferCollectible(
        OrganData storage self,
        address token,
        address caller,
        address to,
        uint256 tokenId
    ) public onlyPerm(self, PERMISSION_WITHDRAW_COLLECTIBLES, caller) {
        // @note Organ must be the owner, approved, or operator of ERC-721.
        IERC721(token).safeTransferFrom(address(this), to, tokenId);
        emit collectibleTransferred(caller, to, tokenId);
    }

    function receiveCollectible(
        OrganData storage self,
        address operator,
        address from,
        uint256 tokenId
    ) public onlyPerm(self, PERMISSION_DEPOSIT_COLLECTIBLES, from) {
        emit collectibleReceived(operator, from, tokenId);
    }

    function transferCoins(
        OrganData storage self,
        address token,
        address caller,
        address to,
        uint256 amount
    ) public onlyPerm(self, PERMISSION_WITHDRAW_COINS, caller) {
        IERC20(token).safeTransfer(to, amount);
        emit coinsTransferred(caller, address(this), to, amount);
    }

    function receiveCoins(
        OrganData storage self,
        address operator,
        address from,
        address to,
        uint256 amount
    ) public onlyPerm(self, PERMISSION_DEPOSIT_COINS, from) {
        emit coinsReceived(operator, from, to, amount);
    }

    function transferEther(
        OrganData storage self,
        address payable to,
        uint256 amount,
        address from
    ) internal onlyPerm(self, PERMISSION_WITHDRAW_ETHER, from) {
        (bool success, ) = to.call{value: amount}('');
        require(success, 'Transfer failed.');
        emit etherTransferred(from, to, amount);
    }

    function receiveEther(
        OrganData storage self,
        uint256 value,
        address from
    ) public onlyPerm(self, PERMISSION_DEPOSIT_ETHER, from) {
        emit etherReceived(from, value);
    }

    /*
        Procedures management.
    */
    function removePermission(
        OrganData storage self,
        address permissionAddress,
        address caller
    ) public onlyPerm(self, PERMISSION_REMOVE_PERMISSIONS, caller) {
        // Check address is already there.
        require(
            self.permissionAddresses.contains(permissionAddress),
            'Record not found.'
        );
        // Remove from Procedures set.
        self.permissionAddresses.remove(permissionAddress);
        self.permissions[permissionAddress] = bytes2(0);
        emit permissionRemoved(caller, permissionAddress);
    }

    function addPermission(
        OrganData storage self,
        address permissionAddress,
        bytes2 permissionValue,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_ADD_PERMISSIONS, caller)
        returns (uint256 index)
    {
        // Check new address is not already there.
        require(
            !self.permissionAddresses.contains(permissionAddress),
            'Duplicate record.'
        );
        // Check new address has permissions.
        require(permissionValue != 0x0000, 'Wrong permissions set.');

        // Store permissions.
        self.permissionAddresses.add(permissionAddress);
        self.permissions[permissionAddress] = permissionValue;
        emit permissionAdded(caller, permissionAddress, permissionValue);
        return index;
    }

    function replacePermission(
        OrganData storage self,
        address oldPermissionAddress,
        address newPermissionAddress,
        bytes2 newPermissionValue,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_REMOVE_PERMISSIONS, caller)
        onlyPerm(self, PERMISSION_ADD_PERMISSIONS, caller)
    {
        // Check old address will be removable before adding.
        require(
            self.permissionAddresses.contains(oldPermissionAddress),
            'Record not found.'
        );
        // Check new address has permissions.
        require(newPermissionValue > 0, 'Wrong permissions set.');

        // Check if we are replacing a master with another, or updating permissions.
        if (oldPermissionAddress != newPermissionAddress) {
            addPermission(
                self,
                newPermissionAddress,
                newPermissionValue,
                caller
            );
            removePermission(self, oldPermissionAddress, caller);
        } else {
            // Update permissions.
            self.permissions[newPermissionAddress] = newPermissionValue;
        }
        // Trigger events.
        emit permissionRemoved(caller, oldPermissionAddress);
        emit permissionAdded(caller, newPermissionAddress, newPermissionValue);
    }

    /**
        Entries management.
    */
    function addEntries(
        OrganData storage self,
        CoreLibrary.Entry[] memory entries,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_ADD_ENTRIES, caller)
        returns (uint256[] memory indexes)
    {
        require(entries.length > 0, 'No entries specified.');
        // uint256 memory initialGas = gasleft();
        indexes = new uint256[](entries.length);

        for (uint256 i = 0; i < entries.length; i++) {
            // If the entry has an address, we check that the address has not been used before.
            if (entries[i].addr != address(0)) {
                require(
                    self.addressIndexInEntries[entries[i].addr] == 0,
                    'Duplicate record.'
                );
            }
            // Adding the entry.
            self.entries.push(entries[i]);
            // Registering entry position relative to its address.
            indexes[i] = self.entries.length - 1;
            self.addressIndexInEntries[entries[i].addr] = indexes[i];
            // Incrementing entries counter.
            self.entriesCount++;
            emit entryAdded(
                caller,
                indexes[i],
                entries[i].addr,
                entries[i].cid
            );
        }

        // Registering the address as active
        return indexes;
    }

    function removeEntries(
        OrganData storage self,
        uint256[] memory indexes,
        address caller
    ) public onlyPerm(self, PERMISSION_REMOVE_ENTRIES, caller) {
        for (uint256 i = 0; i < indexes.length; i++) {
            address addr = self.entries[indexes[i]].addr;
            delete self.entries[indexes[i]];
            self.entriesCount--;
            // Deleting entry index.
            if (addr != address(0)) self.addressIndexInEntries[addr] = 0;
            // Logging event.
            emit entryRemoved(caller, indexes[i]);
        }
    }

    function replaceEntry(
        OrganData storage self,
        uint256 index,
        CoreLibrary.Entry memory entry,
        address caller
    )
        public
        onlyPerm(self, PERMISSION_REMOVE_ENTRIES, caller)
        onlyPerm(self, PERMISSION_ADD_ENTRIES, caller)
    {
        // Check that the replacing address is not registered.
        if (entry.addr != address(0)) {
            require(
                self.addressIndexInEntries[entry.addr] > 0,
                'Record not found.'
            );
        }
        self.addressIndexInEntries[self.entries[index].addr] = 0;
        emit entryRemoved(caller, index);

        self.entries[index] = entry;

        self.addressIndexInEntries[entry.addr] = index;
        emit entryAdded(caller, index, entry.addr, entry.cid);
    }

    function getPermissionsLength(
        OrganData storage self
    ) public view returns (uint256 length) {
        return self.permissionAddresses.length();
    }

    function getPermission(
        OrganData storage self,
        uint256 index
    ) public view returns (address addr, bytes2 perms) {
        addr = self.permissionAddresses.at(index);
        perms = self.permissions[addr];
        return (addr, perms);
    }

    function getEntry(
        OrganData storage self,
        uint256 index
    ) public view returns (CoreLibrary.Entry storage) {
        return self.entries[index];
    }
}

contracts/libraries/ProcedureLibrary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

import '../IOrgan.sol';

/*
    Organigram Protocol - Procedure library.
    This library holds the logic common to all procedures.

    A procedure can affect an organ by :
    - Adding, removing, replacing entries.
    - Adding, removing, replacing procedures.
    - Withdrawing funds and transferring them to another organ.
    The procedure can process a batch of operations in a proposal.
*/

library ProcedureLibrary {
    struct ProcedureData {
        string cid;
        address payable proposers;
        address payable moderators;
        address payable deciders;
        address payable admin;
        mapping(address => uint256) nonces;
        mapping(uint256 => Proposal) proposals;
        uint256 proposalsLength;
        bool withModeration;
        address forwarder;
        address caller;
    }

    struct Proposal {
        address payable creator;
        string cid;
        string blockReason;
        bool presented;
        bool blocked;
        bool adopted;
        bool applied;
        Operation[] operations;
    }

    struct Operation {
        uint256 index;
        address payable target;
        bytes data;
        uint256 value;
        bool processed;
    }

    /**
        Modifiers.
    */
    modifier onlyInOrgan(address payable organAddress, address sender) {
        require(isInOrgan(organAddress, sender), 'Not authorized.');
        _;
    }

    modifier onlyNewProposal(ProcedureData storage self, uint256 proposalKey) {
        require(
            !self.proposals[proposalKey].presented &&
                !self.proposals[proposalKey].adopted &&
                !self.proposals[proposalKey].applied &&
                !self.proposals[proposalKey].blocked,
            'Not authorized'
        );
        _;
    }

    modifier onlyAdoptedProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) {
        require(
            self.proposals[proposalKey].adopted &&
                !self.proposals[proposalKey].applied &&
                !self.proposals[proposalKey].blocked,
            'Not authorized'
        );
        _;
    }

    modifier onlyPresentedProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) {
        require(
            self.proposals[proposalKey].presented &&
                !self.proposals[proposalKey].adopted &&
                !self.proposals[proposalKey].applied &&
                !self.proposals[proposalKey].blocked,
            'Not authorized'
        );
        _;
    }

    /**
        Events.
    */

    event CidUpdated(address from, string cid);
    event AdminUpdated(address from, address admin);
    event ProposalCreated(address indexed creator, uint256 indexed proposalKey);
    event ProposalBlocked(
        address indexed moderator,
        uint256 indexed proposalKey,
        string reason
    );
    event ProposalPresented(
        address indexed presenter,
        uint256 indexed proposalKey
    );
    event ProposalApplied(uint256 indexed proposalKey);

    /*
        Procedure management.
    */

    function init(
        ProcedureData storage self,
        string memory cid,
        address payable proposers,
        address payable moderators,
        address payable deciders,
        bool withModeration, // Adds an extra step where moderators can block a proposal before deciders.
        address forwarder,
        address caller
    ) public {
        self.cid = cid;
        self.proposers = proposers;
        self.moderators = moderators;
        self.deciders = deciders;
        self.withModeration = withModeration;
        self.forwarder = forwarder;
        self.admin = payable(caller);
    }

    /**
        Admin API.
    */

    function updateAdmin(
        ProcedureData storage self,
        address payable admin,
        address caller
    ) public onlyInOrgan(self.admin, caller) {
        self.admin = admin;
        emit AdminUpdated(msg.sender, admin);
    }

    function updateCid(
        ProcedureData storage self,
        string memory cid,
        address caller
    ) public onlyInOrgan(self.admin, caller) {
        self.cid = cid;
        emit CidUpdated(msg.sender, cid);
    }

    /**
        Utils.
    */
    function isInOrgan(
        address payable organ,
        address caller
    ) public view returns (bool) {
        return
            organ == address(0) ||
            organ == caller ||
            IOrgan(organ).getEntryIndexForAddress(caller) != 0;
    }

    /**
        External API.
    */

    /// @notice Proposers can create a proposal with a set of operations.
    /// @dev Merge with proposalCall.
    /// @param cid Metadata describing the proposal, stored on IPFS.
    /// @param operations Set of solidity calls on the procedure or given organ.
    /// @return proposalKey of proposal created.
    function propose(
        ProcedureData storage self,
        string memory cid,
        Operation[] memory operations,
        address caller
    ) public onlyInOrgan(self.proposers, caller) returns (uint256 proposalKey) {
        proposalKey = self.proposalsLength++;
        self.proposals[proposalKey].creator = payable(caller);
        self.proposals[proposalKey].cid = cid;
        for (uint256 i = 0; i < operations.length; ++i) {
            self.proposals[proposalKey].operations.push(
                Operation({
                    index: self.proposals[proposalKey].operations.length,
                    target: operations[i].target,
                    data: operations[i].data,
                    value: operations[i].value,
                    processed: false
                })
            );
        }

        if (!self.withModeration) {
            self.proposals[proposalKey].presented = true;
        }
        emit ProposalCreated(caller, proposalKey);
        return proposalKey;
    }

    /// @notice Block proposal (veto).
    /// @param proposalKey of proposal.
    /// @param reason for blocking the proposal.
    function blockProposal(
        ProcedureData storage self,
        uint256 proposalKey,
        string memory reason,
        address caller
    ) public onlyInOrgan(self.moderators, caller) {
        require(!self.proposals[proposalKey].blocked, 'Already blocked.');
        require(!self.proposals[proposalKey].applied, 'Already applied.');
        self.proposals[proposalKey].blocked = true;
        self.proposals[proposalKey].blockReason = reason;
        emit ProposalBlocked(caller, proposalKey, reason);
    }

    /// @notice Present proposal, in Moderation mode.
    /// @param proposalKey of proposal.
    function presentProposal(
        ProcedureData storage self,
        uint256 proposalKey,
        address caller
    )
        public
        onlyInOrgan(self.moderators, caller)
        onlyNewProposal(self, proposalKey)
    {
        require(self.withModeration, 'Moderation not enabled.');
        self.proposals[proposalKey].presented = true;
        emit ProposalPresented(msg.sender, proposalKey);
    }

    /// @notice Adopt proposal and attempt to apply it.
    /// @dev Should only be called once by parent contract.
    /// @param proposalKey of proposal.
    function _adoptProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) internal onlyPresentedProposal(self, proposalKey) {
        self.proposals[proposalKey].adopted = true;
        applyProposal(self, proposalKey);
    }

    /// @notice Reject proposal and mark it as applied.
    /// @dev Should only be called once by parent contract.
    /// @param proposalKey of proposal.
    function _rejectProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) internal onlyPresentedProposal(self, proposalKey) {
        self.proposals[proposalKey].adopted = false;
        self.proposals[proposalKey].applied = true;
    }

    /// @notice Apply an adopted proposal.
    /// @param proposalKey of proposal.
    function applyProposal(
        ProcedureData storage self,
        uint256 proposalKey
    ) public onlyAdoptedProposal(self, proposalKey) {
        // Process operations.
        for (
            uint256 i = 0;
            i < self.proposals[proposalKey].operations.length;
            ++i
        ) {
            if (!self.proposals[proposalKey].operations[i].processed) {
                if (
                    self.proposals[proposalKey].operations[i].target !=
                    address(0)
                ) {
                    // solhint-disable-next-line avoid-low-level-calls
                    (bool success, ) = self
                        .proposals[proposalKey]
                        .operations[i]
                        .target
                        .call{
                        value: self.proposals[proposalKey].operations[i].value
                    }(self.proposals[proposalKey].operations[i].data);
                    require(
                        success,
                        'Failed to apply proposal: the underlying transaction reverted.'
                    );
                } else {
                    // solhint-disable-next-line avoid-low-level-calls
                    (bool success, ) = address(msg.sender).call{
                        value: self.proposals[proposalKey].operations[i].value
                    }(self.proposals[proposalKey].operations[i].data);
                    require(
                        success,
                        'Failed to apply proposal: the underlying transaction reverted.'
                    );
                }
                self.proposals[proposalKey].operations[i].processed = true;
            }
        }
        self.proposals[proposalKey].applied = true;
        emit ProposalApplied(proposalKey);
    }
}

contracts/MetaGasStation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

import '@openzeppelin/contracts/utils/Context.sol';
import '@openzeppelin/contracts/metatx/ERC2771Forwarder.sol';

contract MetaGasStation is ERC2771Forwarder {
    constructor(string memory name) ERC2771Forwarder(name) {}
}

abstract contract ERC2771Recipient is Context {
    address private _trustedForwarder;

    function _setTrustedForwarder(address forwarder) internal virtual {
        _trustedForwarder = forwarder;
    }

    function isTrustedForwarder(
        address forwarder
    ) public view virtual returns (bool) {
        return forwarder == _trustedForwarder;
    }

    function trustedForwarder() public view virtual returns (address) {
        return _trustedForwarder;
    }

    /**
     * @dev Override for `msg.sender`. Defaults to the original `msg.sender` whenever
     * a call is not performed by the trusted forwarder or the calldata length is less than
     * 20 bytes (an address length).
     */
    function _msgSender() internal view virtual override returns (address) {
        uint256 calldataLength = msg.data.length;
        uint256 contextSuffixLength = _contextSuffixLength();
        if (
            calldataLength >= contextSuffixLength &&
            isTrustedForwarder(msg.sender)
        ) {
            unchecked {
                return
                    address(
                        bytes20(msg.data[calldataLength - contextSuffixLength:])
                    );
            }
        } else {
            return super._msgSender();
        }
    }

    /**
     * @dev Override for `msg.data`. Defaults to the original `msg.data` whenever
     * a call is not performed by the trusted forwarder or the calldata length is less than
     * 20 bytes (an address length).
     */
    function _msgData()
        internal
        view
        virtual
        override
        returns (bytes calldata)
    {
        uint256 calldataLength = msg.data.length;
        uint256 contextSuffixLength = _contextSuffixLength();
        if (
            calldataLength >= contextSuffixLength &&
            isTrustedForwarder(msg.sender)
        ) {
            unchecked {
                return msg.data[:calldataLength - contextSuffixLength];
            }
        } else {
            return super._msgData();
        }
    }

    /**
     * @dev ERC-2771 specifies the context as being a single address (20 bytes).
     */
    function _contextSuffixLength()
        internal
        view
        virtual
        override
        returns (uint256)
    {
        return 20;
    }
}

contracts/Organ.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

import './libraries/CoreLibrary.sol';
import './libraries/OrganLibrary.sol';
import './MetaGasStation.sol';
import './IOrgan.sol';
import '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';
import '@openzeppelin/contracts/interfaces/IERC721.sol';
import '@openzeppelin/contracts/interfaces/IERC777.sol';
import '@openzeppelin/contracts/utils/introspection/ERC165.sol';
import {Initializable as InitializableStatic} from '@openzeppelin/contracts/proxy/utils/Initializable.sol';
import '@openzeppelin/contracts/interfaces/IERC777Recipient.sol';
import '@openzeppelin/contracts/interfaces/IERC777Sender.sol';
import '@openzeppelin/contracts/interfaces/IERC721Receiver.sol';
import '@openzeppelin/contracts/interfaces/IERC1155Receiver.sol';

/// @title Organ contract
/// @author Organigram.ai
/// @notice An organ contains a list of entries, a list of assets (tokens) and a set of procedures. A procedure is a contract that can effect changes on organs. An entry can be a document and/or an address (a wallet or a contract).

contract Organ is
    IOrgan,
    ERC165,
    InitializableStatic,
    IERC777Recipient,
    IERC777Sender,
    IERC721Receiver,
    IERC1155Receiver,
    ERC2771Recipient
{
    using CoreLibrary for CoreLibrary.Entry;
    using OrganLibrary for OrganLibrary.OrganData;
    using EnumerableSet for EnumerableSet.AddressSet;

    // Organ data storage.
    OrganLibrary.OrganData internal organData;
    bytes4 constant INTERFACE_ID = type(IOrgan).interfaceId;

    /**
        Organ API.
    */

    constructor() {
        _disableInitializers();
    }

    // Register EIP165 interfaces for introspection.
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override(ERC165, IERC165) returns (bool) {
        return
            interfaceId == type(IERC777Recipient).interfaceId ||
            interfaceId == type(IERC777Sender).interfaceId ||
            interfaceId == type(IERC721Receiver).interfaceId ||
            interfaceId == type(IERC1155Receiver).interfaceId ||
            interfaceId == INTERFACE_ID ||
            super.supportsInterface(interfaceId);
    }

    function initialize(
        address[] memory permissionAddresses,
        bytes2[] memory permissionValues,
        string memory cid,
        CoreLibrary.Entry[] memory entries,
        address forwarder
    ) external override initializer {
        organData.init(permissionAddresses, permissionValues, cid, entries);
        _setTrustedForwarder(forwarder);
    }

    // Assets.

    receive() external payable {
        organData.receiveEther(msg.value, _msgSender());
    }

    // @todo : Protect ether transfers against re-entrancy attacks.
    function transfer(address payable to, uint256 value) public {
        organData.transferEther(to, value, _msgSender());
    }

    // Implementing ERC-777 receiver interface.
    function tokensReceived(
        address operator,
        address from,
        address to,
        uint256 amount,
        bytes calldata /*data*/,
        bytes calldata /*operatorData*/
    ) external override {
        organData.receiveCoins(operator, from, to, amount);
    }

    function tokensToSend(
        address operator,
        address,
        address to,
        uint256 amount,
        bytes calldata /*userData*/,
        bytes calldata /*operatorData*/
    ) external override {
        organData.transferCoins(_msgSender(), operator, to, amount);
    }

    function transferCoins(
        address token,
        address,
        address to,
        uint256 amount
    ) external {
        organData.transferCoins(token, _msgSender(), to, amount);
    }

    function transferCollectible(
        address token,
        address,
        address to,
        uint256 tokenId
    ) external {
        organData.transferCollectible(token, _msgSender(), to, tokenId);
    }

    // ERC-721 receiver hook.
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes memory /*data*/
    ) public override returns (bytes4) {
        organData.receiveCollectible(operator, from, tokenId);
        return this.onERC721Received.selector;
    }

    // ERC-1155 receiver hooks.
    function onERC1155Received(
        address,
        address,
        uint256,
        uint256,
        bytes memory
    ) public virtual override returns (bytes4) {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(
        address,
        address,
        uint256[] memory,
        uint256[] memory,
        bytes memory
    ) public virtual override returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    function updateCid(string calldata cid) external override {
        organData.updateCid(cid, _msgSender());
    }

    /*
        API for Procedure contract.
    */

    function addEntries(
        CoreLibrary.Entry[] memory entries
    ) external override returns (uint256[] memory indexes) {
        return organData.addEntries(entries, _msgSender());
    }

    function removeEntries(uint256[] memory indexes) external override {
        organData.removeEntries(indexes, _msgSender());
    }

    function replaceEntry(
        uint256 index,
        CoreLibrary.Entry memory entry
    ) external override {
        organData.replaceEntry(index, entry, _msgSender());
    }

    // @TODO : Should be plural.
    function addPermission(
        address permissionAddress,
        bytes2 permissionValue
    ) external override {
        organData.addPermission(
            permissionAddress,
            permissionValue,
            _msgSender()
        );
    }

    // @TODO : Should be plural.
    function removePermission(address permissionAddress) external override {
        organData.removePermission(permissionAddress, _msgSender());
    }

    function replacePermission(
        address oldPermissionAddress,
        address newPermissionAddress,
        bytes2 newPermissionValue
    ) external override {
        organData.replacePermission(
            oldPermissionAddress,
            newPermissionAddress,
            newPermissionValue,
            _msgSender()
        );
    }

    function setCallPolicy(
        address target,
        bytes4 selector,
        IOrgan.ParamConstraintInput[] calldata constraints,
        address[] calldata whitelistedAddresses
    ) external override {
        uint256 constraintsLength = constraints.length;
        OrganLibrary.ParamConstraint[] memory converted = new OrganLibrary.ParamConstraint[](constraintsLength);
        for (uint256 i = 0; i < constraintsLength; i++) {
            converted[i] = OrganLibrary.ParamConstraint({
                index: constraints[i].index,
                constraintType: OrganLibrary.ParamConstraintType(uint8(constraints[i].constraintType)),
                minValue: constraints[i].minValue,
                maxValue: constraints[i].maxValue,
                exactValue: constraints[i].exactValue
            });
        }
        organData.setCallPolicy(
            target,
            selector,
            converted,
            whitelistedAddresses,
            _msgSender()
        );
    }

    function removeCallPolicy(address target, bytes4 selector) external override {
        organData.removeCallPolicy(target, selector, _msgSender());
    }

    function executeWhitelisted(
        address target,
        uint256 value,
        bytes calldata data
    ) external override returns (bytes memory result) {
        return organData.executeWhitelisted(target, value, data, _msgSender());
    }

    /*
        Accessors.
    */

    function getOrgan()
        external
        view
        override
        returns (
            string memory cid,
            uint256 permissionsLength,
            uint256 entriesLength,
            uint256 entriesCount,
            bytes4 interfaceId
        )
    {
        return (
            organData.cid,
            organData.getPermissionsLength(),
            organData.entries.length,
            organData.entriesCount,
            INTERFACE_ID
        );
    }

    function getEntryIndexForAddress(
        address addr
    ) external view override returns (uint256 index) {
        return organData.addressIndexInEntries[addr];
    }

    function getEntry(
        uint256 index
    ) external view override returns (CoreLibrary.Entry memory entry) {
        return organData.getEntry(index);
    }

    function getPermission(
        uint256 index
    ) external view override returns (address addr, bytes2 perms) {
        return organData.getPermission(index);
    }

    function getPermissions(
        address addr
    ) external view override returns (bytes2 perms) {
        return organData.permissions[addr];
    }

    function getCallPolicy(
        address target,
        bytes4 selector
    )
        external
        view
        override
        returns (
            bool enabled,
            uint256 constraintsLength,
            uint256 whitelistedAddressesLength
        )
    {
        bytes32 policyKey = OrganLibrary._callPolicyKey(target, selector);
        OrganLibrary.CallPolicy storage policy = organData.callPolicies[policyKey];
        return (
            policy.enabled,
            policy.constraints.length,
            organData.callPolicyWhitelistedAddresses[policyKey].length()
        );
    }

    function getCallPolicyConstraint(
        address target,
        bytes4 selector,
        uint256 index
    )
        external
        view
        override
        returns (
            uint8 paramIndex,
            IOrgan.ParamConstraintType constraintType,
            bytes32 minValue,
            bytes32 maxValue,
            bytes32 exactValue
        )
    {
        bytes32 policyKey = OrganLibrary._callPolicyKey(target, selector);
        OrganLibrary.ParamConstraint storage constraint = organData.callPolicies[policyKey].constraints[index];
        return (
            constraint.index,
            IOrgan.ParamConstraintType(uint8(constraint.constraintType)),
            constraint.minValue,
            constraint.maxValue,
            constraint.exactValue
        );
    }

    function isCallPolicyWhitelistedAddress(
        address target,
        bytes4 selector,
        address candidate
    ) external view override returns (bool) {
        bytes32 policyKey = OrganLibrary._callPolicyKey(target, selector);
        return organData.callPolicyWhitelistedAddresses[policyKey].contains(candidate);
    }
}

contracts/OrganigramClient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

import './Organ.sol';
import './Asset.sol';
import './IAsset.sol';
import './MetaGasStation.sol';
import './libraries/CoreLibrary.sol';
import '@openzeppelin/contracts/utils/introspection/ERC165Checker.sol';
import '@openzeppelin/contracts/proxy/Clones.sol';
import '@openzeppelin/contracts/utils/Address.sol';

contract OrganigramClient is ERC2771Recipient {
    using CoreLibrary for CoreLibrary.Entry;
    address payable public organ; // Cloneable organ implementation.
    address payable public asset; // Cloneable asset implementation.
    address payable public proceduresRegistry; // Organ with the addresses of supported procedures implementations.

    event organDeployed(address payable organ);
    event assetDeployed(address payable asset);
    event procedureDeployed(
        address payable procedureType,
        address payable procedure
    );

    struct DeployOrganArgs {
        address[] permissionAddresses;
        bytes2[] permissionValues;
        string cid;
        CoreLibrary.Entry[] entries;
        bytes32 salt;
    }
    struct DeployProcedureArgs {
        address payable procedureType;
        bytes data;
        bytes32 salt;
    }
    struct DeployAssetArgs {
        string name;
        string symbol;
        uint256 initialSupply;
        bytes32 salt;
    }

    constructor(string memory cid, address trustedForwarder, bytes32 salt) {
        _setTrustedForwarder(trustedForwarder);
        organ = payable(address(new Organ()));
        asset = payable(address(new Asset()));

        // Create permissions arguments for the procedures registry organ.
        address[] memory permissionAddresses = new address[](1);
        bytes2[] memory permissionValues = new bytes2[](1);

        permissionAddresses[0] = _msgSender(); // Set the sender as default admin...
        permissionValues[0] = bytes2(0xffff); // ...with all permissions.

        CoreLibrary.Entry[] memory emptyEntries = new CoreLibrary.Entry[](0);

        proceduresRegistry = deployOrgan(
            permissionAddresses,
            permissionValues,
            cid,
            emptyEntries,
            salt
        );
    }

    function deployOrgan(
        address[] memory _permissionAddresses,
        bytes2[] memory _permissionValues,
        string memory cid,
        CoreLibrary.Entry[] memory entries,
        bytes32 salt
    ) public returns (address payable clone) {
        require(
            _permissionAddresses.length == _permissionValues.length,
            'LengthMismatch'
        );

        // If no permissions are provided, set the sender as admin with all permissions.
        if (_permissionAddresses.length == 0) {
            _permissionAddresses = new address[](1);
            _permissionValues = new bytes2[](1);
            _permissionAddresses[0] = _msgSender();
            _permissionValues[0] = bytes2(0xffff);
        }

        // Clone organ and initialize it.
        clone = payable(Clones.cloneDeterministic(organ, salt));
        Organ(clone).initialize(
            _permissionAddresses,
            _permissionValues,
            cid,
            entries,
            trustedForwarder()
        );
        emit organDeployed(clone);
        return clone;
    }

    function deployOrgans(
        DeployOrganArgs[] memory batch
    ) public returns (address payable[] memory clones) {
        clones = new address payable[](batch.length);

        for (uint256 i = 0; i < batch.length; i++) {
            clones[i] = deployOrgan(
                batch[i].permissionAddresses,
                batch[i].permissionValues,
                batch[i].cid,
                batch[i].entries,
                batch[i].salt
            );
        }
        return clones;
    }

    function deployAsset(
        string memory name,
        string memory symbol,
        uint256 initialSupply,
        bytes32 salt
    ) public returns (address payable clone) {
        clone = payable(Clones.cloneDeterministic(address(asset), salt));
        IAsset(clone).initialize(name, symbol, _msgSender(), initialSupply);

        emit assetDeployed(clone);
        return clone;
    }

    function deployAssets(
        DeployAssetArgs[] memory batch
    ) public returns (address payable[] memory clones) {
        clones = new address payable[](batch.length);

        for (uint256 i = 0; i < batch.length; i++) {
            clones[i] = deployAsset(
                batch[i].name,
                batch[i].symbol,
                batch[i].initialSupply,
                batch[i].salt
            );
        }
        return clones;
    }

    function deployProcedure(
        address payable procedureType,
        bytes memory data,
        bytes32 salt
    ) public returns (address payable procedure) {
        require(
            ERC165Checker.supportsInterface(procedureType, 0x71dbd330),
            'Not a procedure.'
        );
        require(
            Organ(proceduresRegistry).getEntryIndexForAddress(procedureType) >
                0,
            'Procedure not found.'
        );
        procedure = payable(Clones.cloneDeterministic(procedureType, salt));
        emit procedureDeployed(procedureType, procedure);
        // NB: The initialize method will need to be called immediately
        // if not through the data parameter.
        if (data.length > 0) {
            Address.functionCall(procedure, data);
        }
        return procedure;
    }

    function deployProcedures(
        DeployProcedureArgs[] memory batch
    ) public returns (address payable[] memory created) {
        created = new address payable[](batch.length);

        for (uint256 i = 0; i < batch.length; i++) {
            created[i] = deployProcedure(
                batch[i].procedureType,
                batch[i].data,
                batch[i].salt
            );
        }
        return created;
    }

    function deployOrganigram(
        DeployOrganArgs[] memory organBatch,
        DeployAssetArgs[] memory assetBatch,
        DeployProcedureArgs[] memory procedureBatch
    )
        public
        returns (
            address payable[] memory organsDeployed,
            address payable[] memory assetsDeployed,
            address payable[] memory proceduresDeployed
        )
    {
        organsDeployed = deployOrgans(organBatch);
        assetsDeployed = deployAssets(assetBatch);
        proceduresDeployed = deployProcedures(procedureBatch);
        return (organsDeployed, assetsDeployed, proceduresDeployed);
    }

    function registerProcedures(CoreLibrary.Entry[] memory entries) external {
        // Only valid procedures
        for (uint256 i; i < entries.length; ++i) {
            require(
                ERC165Checker.supportsInterface(entries[i].addr, 0x71dbd330),
                'An entry in parameters is not a valid procedure.'
            );
        }
        Organ(proceduresRegistry).addEntries(entries);
    }
}

contracts/Procedure.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

import './libraries/ProcedureLibrary.sol';
import './MetaGasStation.sol';
import '@openzeppelin/contracts/utils/introspection/ERC165.sol';
import '@openzeppelin/contracts/utils/cryptography/ECDSA.sol';
import '@openzeppelin/contracts/utils/cryptography/EIP712.sol';
import {Initializable as InitializableStatic} from '@openzeppelin/contracts/proxy/utils/Initializable.sol';
import '@openzeppelin/contracts/utils/ReentrancyGuard.sol';

/*
    A procedure defines a set of operations compiled in a proposal.
    The procedure dictates the way the proposal can be applied.
*/
contract Procedure is
    ERC165,
    InitializableStatic,
    ReentrancyGuard,
    ERC2771Recipient,
    EIP712
{
    using ProcedureLibrary for ProcedureLibrary.ProcedureData;
    using ProcedureLibrary for ProcedureLibrary.Operation;
    ProcedureLibrary.ProcedureData internal procedureData;
    bytes4 public constant INTERFACE_ID = 0x71dbd330;
    bytes32 internal constant OPERATION_TYPEHASH =
        keccak256(
            'Operation(uint256 index,address target,bytes data,uint256 value)'
        );
    bytes32 internal constant PROPOSAL_TYPEHASH =
        keccak256(
            'Proposal(string cid,bytes32 operationsHash,uint256 nonce,uint256 deadline)'
        );
    bytes32 internal constant PRESENT_PROPOSAL_TYPEHASH =
        keccak256(
            'PresentProposal(uint256 proposalKey,uint256 nonce,uint256 deadline)'
        );
    bytes32 internal constant BLOCK_PROPOSAL_TYPEHASH =
        keccak256(
            'BlockProposal(uint256 proposalKey,string reason,uint256 nonce,uint256 deadline)'
        );
    bytes32 internal constant APPLY_PROPOSAL_TYPEHASH =
        keccak256(
            'ApplyProposal(uint256 proposalKey,uint256 nonce,uint256 deadline)'
        );

    /**
        Modifiers.
    */
    modifier onlyInOrgan(address payable organAddress) {
        require(
            ProcedureLibrary.isInOrgan(organAddress, _msgSender()),
            'Not authorized'
        );
        _;
    }

    modifier onlyDeciders() {
        require(
            ProcedureLibrary.isInOrgan(procedureData.deciders, _msgSender()),
            'Not authorized'
        );
        _;
    }

    /**
        Procedure constructor.
    */
    constructor() EIP712('Organigram Procedure', '1') {
        _disableInitializers();
    }

    // Register EIP165 interfaces for introspection.
    function supportsInterface(
        bytes4 interfaceId
    ) public view virtual override returns (bool) {
        // @todo : Use type(IProcedure).interfaceId
        return
            interfaceId == INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    function initialize(
        string memory _cid,
        address payable _proposers,
        address payable _moderators,
        address payable _deciders,
        bool _withModeration,
        address _trustedForwarder
    ) public virtual initializer {
        procedureData.init(
            _cid,
            _proposers,
            _moderators,
            _deciders,
            _withModeration,
            _trustedForwarder,
            _msgSender()
        );
        _setTrustedForwarder(_trustedForwarder);
    }

    /**
        Public API : Procedure Cid and Admin.
    */
    function updateCid(string memory cid) public {
        procedureData.updateCid(cid, _msgSender());
    }

    function updateAdmin(address payable admin) public {
        procedureData.updateAdmin(admin, _msgSender());
    }

    /**
        Public API : Proposals creation and update.
    */
    function propose(
        string memory cid,
        ProcedureLibrary.Operation[] memory operations
    ) public virtual returns (uint256 proposalKey) {
        return procedureData.propose(cid, operations, _msgSender());
    }

    function proposeBySig(
        string calldata cid,
        ProcedureLibrary.Operation[] calldata operations,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual returns (uint256 proposalKey) {
        bytes32 operationsHash = _hashOperations(operations);
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    PROPOSAL_TYPEHASH,
                    keccak256(bytes(cid)),
                    operationsHash,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        return procedureData.propose(cid, operations, signer);
    }

    /// @notice The procedure can override this method.
    function blockProposal(
        uint256 proposalKey,
        string calldata reason
    ) public virtual {
        procedureData.blockProposal(proposalKey, reason, _msgSender());
    }

    function blockProposalBySig(
        uint256 proposalKey,
        string calldata reason,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual {
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    BLOCK_PROPOSAL_TYPEHASH,
                    proposalKey,
                    keccak256(bytes(reason)),
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        procedureData.blockProposal(proposalKey, reason, signer);
    }

    /// @notice When moderation is enabled, moderators must accept the proposal.
    function presentProposal(uint256 proposalKey) public virtual {
        procedureData.presentProposal(proposalKey, _msgSender());
    }

    function presentProposalBySig(
        uint256 proposalKey,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual {
        address signer = _recoverTypedSigner(
            keccak256(
                abi.encode(
                    PRESENT_PROPOSAL_TYPEHASH,
                    proposalKey,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        procedureData.presentProposal(proposalKey, signer);
    }

    /// @notice The procedure calls this method directly to adopt and apply a proposal.
    function _adoptProposal(uint256 proposalKey) internal virtual nonReentrant {
        procedureData._adoptProposal(proposalKey);
    }

    /// @notice The procedure calls this method directly to reject a proposal.
    function _rejectProposal(uint256 proposalKey) internal virtual nonReentrant {
        procedureData._rejectProposal(proposalKey);
    }

    /// @notice Apply proposal.
    function applyProposal(uint256 proposalKey) public virtual nonReentrant {
        procedureData.applyProposal(proposalKey);
    }

    function applyProposalBySig(
        uint256 proposalKey,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) public virtual nonReentrant {
        _recoverTypedSigner(
            keccak256(
                abi.encode(
                    APPLY_PROPOSAL_TYPEHASH,
                    proposalKey,
                    nonce,
                    deadline
                )
            ),
            nonce,
            deadline,
            signature
        );
        procedureData.applyProposal(proposalKey);
    }

    /*
        Accessors.
    */
    function getProcedure()
        public
        view
        returns (
            string memory cid,
            address payable proposers,
            address payable moderators,
            address payable deciders,
            bool withModeration,
            uint256 proposalsLength,
            bytes4 interfaceId
        )
    {
        return (
            procedureData.cid,
            procedureData.proposers,
            procedureData.moderators,
            procedureData.deciders,
            procedureData.withModeration,
            procedureData.proposalsLength,
            INTERFACE_ID
        );
    }

    function getProposal(
        uint256 proposalKey
    ) public view returns (ProcedureLibrary.Proposal memory) {
        return procedureData.proposals[proposalKey];
    }

    function getNonce(address account) public view returns (uint256) {
        return procedureData.nonces[account];
    }

    function _recoverTypedSigner(
        bytes32 structHash,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) internal returns (address signer) {
        require(deadline >= block.timestamp, 'Signature expired');
        signer = ECDSA.recover(_hashTypedDataV4(structHash), signature);
        require(procedureData.nonces[signer] == nonce, 'Invalid nonce');
        procedureData.nonces[signer] = nonce + 1;
    }

    function _hashOperation(
        ProcedureLibrary.Operation memory operation
    ) internal pure returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    OPERATION_TYPEHASH,
                    operation.index,
                    operation.target,
                    keccak256(operation.data),
                    operation.value
                )
            );
    }

    function _hashOperations(
        ProcedureLibrary.Operation[] calldata operations
    ) internal pure returns (bytes32) {
        bytes32[] memory operationHashes = new bytes32[](operations.length);
        for (uint256 i = 0; i < operations.length; i++) {
            operationHashes[i] = _hashOperation(operations[i]);
        }
        return keccak256(abi.encodePacked(operationHashes));
    }
}

contracts/procedures/ERC20Vote.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
pragma experimental ABIEncoderV2;

import './Vote.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';

/// @title ERC20 Vote Procedure.
/// @notice An ERC20 Vote Procedure will execute operations based on the decision of a vote. The voter's relative weight in the vote depends on the amount of tokens they own of a certain asset.
contract ERC20VoteProcedure is VoteProcedure {
    /// @notice tokenContract is an ERC20 token contract representing the rights to vote.
    IERC20 public tokenContract;

    /// @notice Prevent using the non-ERC20 initializer inherited from VoteProcedure.
    function initialize(
        string memory,
        address payable,
        address payable,
        address payable,
        bool,
        address,
        uint32,
        uint32,
        uint32
    ) public pure override {
        revert('Missing parameters');
    }

    /// @notice Initialize the procedure.
    /// @param _metadata The procedure metadata.
    /// @param _proposers The organ whose entries will be allowed to propose proposals.
    /// @param _moderators The organ whose entries will be allowed to moderate proposals.
    /// @param _deciders The organ whose entries will be allowed to adopt or refect proposals.
    /// @param _withModeration Whether or not the procedure requires moderation.
    /// @param _trustedForwarder The trusted forwarder contract.
    /// @param _quorumSize The minimum percentage of votes required to validate a election.
    /// @param _voteDuration Duration of vote in seconds.
    /// @param _majoritySize The minimum percentage of votes required to validate a election.
    /// @param _tokenContract The ERC20 token contract representing the rights to vote.
    function initialize(
        string memory _metadata,
        address payable _proposers,
        address payable _moderators,
        address payable _deciders,
        bool _withModeration,
        address _trustedForwarder,
        uint32 _quorumSize,
        uint32 _voteDuration,
        uint32 _majoritySize,
        address _tokenContract
    ) public virtual {
        super.initialize(
            _metadata,
            _proposers,
            _moderators,
            _deciders,
            _withModeration,
            _trustedForwarder,
            _quorumSize,
            _voteDuration,
            _majoritySize
        );
        // @todo : Check if tokenContract implements ERC20.
        tokenContract = IERC20(_tokenContract);
    }

    /// @notice Count votes after election has ended.
    /// @param proposalKey The key used to identify the proposal.
    /// @return approved True if the election has been approved.
    function count(
        uint256 proposalKey
    ) public view override returns (bool approved) {
        require(elections[proposalKey].start > 0, 'No election');
        require(
            block.timestamp >= (elections[proposalKey].start + voteDuration),
            'Election not ended'
        );
        if (procedureData.deciders != address(0)) {
            (, , , uint256 decidersCount, ) = IOrgan(procedureData.deciders)
                .getOrgan();
            require(
                elections[proposalKey].votesCount >
                    ((quorumSize * decidersCount) / 100000),
                'Quorum has not been reached'
            );
        }
        uint256 approvals;
        uint256 objections;
        for (uint256 i = 0; i < elections[proposalKey].voters.length; i++) {
            if (
                elections[proposalKey]
                    .votes[elections[proposalKey].voters[i]]
                    .voted
            ) {
                if (
                    elections[proposalKey]
                        .votes[elections[proposalKey].voters[i]]
                        .approved
                ) {
                    approvals += tokenContract.balanceOf(
                        elections[proposalKey].voters[i]
                    );
                } else {
                    objections += tokenContract.balanceOf(
                        elections[proposalKey].voters[i]
                    );
                }
            }
        }
        require((approvals + objections) > 0, 'No vote');
        return (approvals >
            (((approvals + objections) * majoritySize) / 100000));
    }
}

